(()=>{'use strict';
const D=window.HSK_DATA,E=window.HSK_ENGINE,KEY='hsk-studio-v1';
const G=window.HSK_GRAMMAR_GUIDE;
const guideExamples=new Map(),guidePinyin=new Map();
for(const topic of G?.topics||[])for(const ex of topic.examples){guideExamples.set(ex.id,{...ex,level:4,family:topic.id,answer:ex.text,explanation:topic.explanation+' '+topic.tip,tag:topic.title});guidePinyin.set(ex.text,ex.py);}
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'⌂',papers:'▦',practice:'✎',cards:'▤',grammar:'文',review:'↺',progress:'▥',plan:'✓',settings:'⚙'};
const labels={home:'Study dashboard',papers:'Mock exams',practice:'Practice lab',cards:'Flashcards',grammar:'Grammar guide',review:'Review notebook',progress:'Your progress',plan:'Revision planner',settings:'Settings & help'};
const defaults=()=>({version:1,level:3,settings:{theme:'light',font:26,voice:'',speed:1,goal:30},active:null,history:[],mistakes:{},bookmarks:{},cards:{},days:{},tags:{},plan:{}});
let S=defaults(),storageOK=true;try{const raw=localStorage.getItem(KEY);if(raw)S=validate(JSON.parse(raw));}catch(e){storageOK=false;}
let view='home',session=null,index=0,cardIndex=0,cardFlipped=false,cardFilter='due',reviewTab='mistakes',paperSearch='',paperFilter='all',voices=[],speechToken=0,flashOrder=null;
let grammarSearch='',grammarFilter='all';
function validate(x){if(!x||x.version!==1||![3,4].includes(x.level))throw Error('Not a supported HSK Studio backup.');const s=defaults();s.level=x.level;s.settings={...s.settings,...x.settings};if(!['light','dark'].includes(s.settings.theme))s.settings.theme='light';s.settings.font=Math.min(36,Math.max(20,Number(s.settings.font)||26));s.settings.speed=Math.min(1.2,Math.max(.6,Number(s.settings.speed)||1));s.settings.goal=Math.min(200,Math.max(5,Number(s.settings.goal)||30));s.history=Array.isArray(x.history)?x.history.filter(h=>h&&[3,4].includes(h.level)&&typeof h.title==='string').slice(-200).map(h=>({...h,correct:Math.max(0,Number(h.correct)||0),total:Math.max(0,Number(h.total)||0),unrated:Math.max(0,Number(h.unrated)||0),sections:Array.isArray(h.sections)?h.sections.map(z=>({name:String(z.name),total:Number(z.total)||0,correct:Number(z.correct)||0})):[]})):[];for(const k of ['mistakes','bookmarks','cards','days','tags','plan'])if(x[k]&&typeof x[k]==='object'&&!Array.isArray(x[k]))s[k]=x[k];for(const k in s.days)s.days[k]=Math.max(0,Number(s.days[k])||0);for(const k in s.mistakes)if(s.mistakes[k])s.mistakes[k].count=Math.max(0,Number(s.mistakes[k].count)||0);if(x.active&&Array.isArray(x.active.questions)&&x.active.questions.length<=150&&x.active.questions.every(q=>q&&typeof q.id==='string'&&['choice','tf','picture-choice','order','sequence','character','free','dictation','gap'].includes(q.type))){s.active=x.active;}return s;}
function save(){if(session&&!session.finished)S.active=session;try{localStorage.setItem(KEY,JSON.stringify(S));storageOK=true;}catch(e){storageOK=false;toast('Browser storage is full or blocked. Export a backup to keep your progress.');}}
function dateKey(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),4500);}
function py(s){if(!/[\u4e00-\u9fff]/.test(String(s||'')))return '';return D.pinyin[s]||guidePinyin.get(s)||String(s||'').split('').map(c=>D.charPinyin?.[c]||c).join(' ');}
function zh(s,cls=''){return `<span lang="zh-CN" class="zh ${cls}">${esc(s)}</span>`;}
function btn(text,act,extra='',kind=''){return `<button class="btn ${kind}" data-action="${act}" ${extra}>${text}</button>`;}
function qkey(q){let h=0;for(const c of String(q.prompt||q.text||''))h=(Math.imul(31,h)+c.charCodeAt(0))|0;return `${q.sourceId||q.id}:${q.type}:${h}`;}
function minutes(n){return `${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;}
function current(){return session?.questions[index];}
function stats(){let h=S.history.filter(x=>x.level===S.level),total=h.reduce((a,x)=>a+(x.total||0),0),correct=h.reduce((a,x)=>a+(x.correct||0),0),completed=new Set(h.filter(x=>x.paper).map(x=>x.paper));return {h,total,correct,accuracy:total?Math.round(correct/total*100):0,completed:completed.size};}
function dueMistakes(){return Object.values(S.mistakes).filter(x=>x.q?.level===S.level&&!x.resolved);}
function paperStatus(n,sec){return S.history.some(x=>x.level===S.level&&x.paper===n&&(x.section===sec||x.section==='all'));}
function shell(content){document.body.classList.toggle('dark',S.settings.theme==='dark');document.documentElement.style.setProperty('--zh',S.settings.font+'px');$('#app').innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><div class="brand"><span class="brand-mark">学</span> HSK Studio</div><p class="brand-sub">A LITTLE EVERY DAY</p><nav aria-label="Main navigation">${Object.keys(labels).map(k=>`<button class="navbtn ${view===k?'active':''}" data-action="nav" data-view="${k}"><span class="navico" aria-hidden="true">${icons[k]}</span>${labels[k]}</button>`).join('')}</nav><div class="sidebar-foot"><span class="tag dark">HSK 2.0 EDITION</span><p>Small steps. Real progress.</p><p>Saved on this device · No account</p></div></aside><div class="main-wrap"><header class="topbar"><div class="row"><button class="mobile-menu" data-action="menu" aria-label="Toggle navigation">☰</button><span class="topbar-label">Your space to learn, practise, and grow.</span></div><div class="top-right"><span class="small muted"><span class="badge-dot"></span><span id="connection">${navigator.onLine?'Ready to study':'Offline mode'}</span></span><div class="level-switch" aria-label="Study level"><button data-action="level" data-level="3" class="${S.level===3?'active':''}" aria-pressed="${S.level===3}">HSK 3</button><button data-action="level" data-level="4" class="${S.level===4?'active':''}" aria-pressed="${S.level===4}">HSK 4</button></div></div></header><main id="main" tabindex="-1">${!storageOK?'<div class="notice warn">Local storage is unavailable. Export your progress before closing this page.</div>':''}${content}<p class="footer-note">Original study material · HSK 2.0 practice · Not affiliated with Chinese Testing International.</p></main></div></div>`;}
function heading(kicker,title,desc=''){return `<p class="eyebrow">${kicker}</p><h1 style="margin:10px 0 14px">${title}</h1>${desc?`<p class="muted">${desc}</p>`:''}`;}
function render(){if(view==='exam'){renderExam();return;}if(view==='results'){renderResults();return;}let content=({home:home,papers:papers,practice:practice,cards:cards,grammar:grammar,review:review,progress:progress,plan:plan,settings:settings})[view]();shell(content);}
function home(){const st=stats(),today=S.days[dateKey()]||0;return `<div class="hero"><div><span class="tag">YOUR FINAL PREPARATION, SIMPLIFIED</span><h1>A little practice.<br>A lot more confidence.</h1><p>Listen closely. Read with purpose. Write with confidence. Make your next HSK session count.</p><div class="row mt">${btn('Explore mock exams <span aria-hidden="true">↗</span>','nav','data-view="papers"')}${S.active?btn('Resume session →','resume','','secondary'):btn('Start a 10-question warm-up','quick','','secondary')}</div></div><div class="hero-art" aria-hidden="true"><div class="hanzi">加油</div><p>JIĀ YÓU · KEEP GOING</p><span class="tag">ONE QUESTION AT A TIME</span></div></div><div class="grid four mt"><div class="card stat"><span class="eyebrow">Practice papers</span><div class="stat-num">50 <span class="small muted">/ level</span></div><span class="small muted">Every section, full question counts</span></div><div class="card stat"><span class="eyebrow">Your accuracy</span><div class="stat-num">${st.total?st.accuracy+'%':'—'}</div><span class="small muted">${st.total} scored answers in finished sessions</span></div><div class="card stat"><span class="eyebrow">Today's practice</span><div class="stat-num">${today}<span class="small muted"> / ${S.settings.goal}</span></div><span class="small muted">Answers checked + flashcards reviewed</span></div><div class="card stat"><span class="eyebrow">Ready to revisit</span><div class="stat-num">${dueMistakes().length}</div><span class="small muted">Mistakes turn into your next lesson</span></div></div><div class="section-head"><h2>Choose your level</h2><span class="small muted">HSK 2.0 syllabus</span></div><div class="grid two">${[3,4].map(l=>`<button class="level-card ${l===S.level?'selected':''}" data-action="level-papers" data-level="${l}"><div class="row between"><span class="tag">${l===3?'BUILD YOUR FOUNDATION':'TAKE THE NEXT STEP'}</span><span aria-hidden="true">↗</span></div><div class="row mt"><span class="level-number">HSK ${l}</span><span class="muted">${l===3?'600':'1,200'}-word syllabus</span></div><p class="small muted mt">${l===3?'40 listening · 30 reading · 10 writing':'45 listening · 40 reading · 15 writing'}</p><span class="small">50 papers · Study one section or take the whole paper</span></button>`).join('')}</div><div class="section-head"><h2>A good place to begin</h2>${btn('See all practice →','nav','data-view="practice"','ghost tiny')}</div><div class="grid three">${[['🎧','Train your ear','Listen, replay, and build confidence with Mandarin.','listen-drill'],['文','Make grammar click','See the pattern, then put it into practice.','grammar-drill'],['↺','Learn from mistakes','Return to the questions that need another look.','mistake-drill']].map(([icon,title,desc,act])=>`<div class="card"><div class="feature-icon">${icon}</div><h3>${title}</h3><p class="muted small">${desc}</p>${btn('Start practising →',act,'','secondary tiny')}</div>`).join('')}</div><div class="notice mt">These are full-length practice forms assembled from a shared question bank. Scenarios and grammar repeat across forms. Listening uses synthesised speech and picture tasks use simple illustrations; this is practice, not an exact simulation of official paper recordings.</div>`;}
function papers(){return heading('THE EXAM ROOM',`HSK ${S.level} mock exams`,'Choose a paper, then practise a section or take a timed full paper.')+`<div class="toolbar"><div class="field"><label for="paper-search">Find a paper</label><input id="paper-search" type="search" placeholder="Paper number, e.g. 12" value="${esc(paperSearch)}"></div><div class="field"><label for="paper-filter">Show</label><select id="paper-filter"><option value="all" ${paperFilter==='all'?'selected':''}>All papers</option><option value="new" ${paperFilter==='new'?'selected':''}>Not fully completed</option><option value="done" ${paperFilter==='done'?'selected':''}>All sections completed</option></select></div><span class="small muted">${S.level===3?'80 questions per paper':'100 questions per paper'} · 50 fixed practice forms</span></div><div id="paper-grid" class="test-grid">${paperGrid()}</div>`;}
function paperGrid(){return Array.from({length:50},(_,i)=>i+1).filter(n=>!paperSearch||String(n).includes(paperSearch)).filter(n=>{let done=['listening','reading','writing'].every(s=>paperStatus(n,s));return paperFilter==='all'||(paperFilter==='done'?done:!done);}).map(n=>`<article class="card test-card"><div class="row between"><span class="test-num">${String(n).padStart(2,'0')}</span><span class="tag">${['listening','reading','writing'].filter(s=>paperStatus(n,s)).length}/3 sections</span></div><h3>Practice paper ${n}</h3><p class="small muted">HSK ${S.level} · ${S.level===3?'80':'100'} questions</p><div class="test-sections">${['listening','reading','writing'].map(s=>btn(`${paperStatus(n,s)?'✓ ':''}${s[0].toUpperCase()+s.slice(1)}`,'setup',`data-paper="${n}" data-section="${s}"`,'secondary tiny')).join('')}</div>${btn('Take full paper →','setup',`data-paper="${n}" data-section="all"`,'ghost tiny')}</article>`).join('')||'<p class="muted">No matching papers. Try another number or filter.</p>';}
function practice(){return heading('SMALL SESSIONS. STRONGER SKILLS.', 'Your practice lab','Mix focused drills with full papers. Ten careful answers can be more useful than rushing through a hundred.')+`<div class="grid three mt">${[
['🎧','Listening sprint','10 listening questions with replay and explanations.','listen-drill'],['✎','Dictation','Listen to a complete sentence and type what you hear.','dictation'],['文','Grammar gaps','Fill the blank and understand why the word fits.','grammar-drill'],['↔','Sentence builder','Arrange word chunks into grammatical sentences.','order-drill'],['▤','Reading sprint','Read 10 short passages and identify the key facts.','read-drill'],['字','Character recall','Use a pinyin hint to write the missing character.','char-drill'],['↺','Mistake workout','Retry your unresolved mistakes from this level.','mistake-drill'],['☆','Saved questions','Practise questions you have bookmarked.','bookmark-drill'],['☀','Daily challenge','A fixed mix of 10 questions for today.','daily'],['◈','Vocabulary quiz','Choose meanings from the focused revision deck.','vocab-quiz'],['⌁','Picture writing','Write your own sentence, then compare a model.','picture-drill'],['⚡','Mixed warm-up','Ten questions drawn from the selected level.','quick']].map(([ic,title,desc,act])=>`<div class="card"><div class="feature-icon">${ic}</div><h3>${title}</h3><p class="muted small">${desc}</p>${btn('Start →',act,'','secondary tiny')}</div>`).join('')}</div><div class="notice mt">Dictation checks the written sentence after removing punctuation and spaces. Word-order exercises use a model order; a different valid order may need your own review. Open writing is self-assessed.</div>`;}
function vocabDeck(){return D.vocab.filter(x=>x.level===S.level);}
function filteredCards(){const deck=vocabDeck();return cardFilter==='all'?deck:deck.filter(x=>!S.cards[x.id]||S.cards[x.id].due<=Date.now());}
function cards(){let deck=filteredCards();cardIndex=Math.min(cardIndex,Math.max(0,deck.length-1));let c=deck[cardIndex];return heading('REMEMBER A LITTLE LONGER','Vocabulary flashcards',`${vocabDeck().length} focused revision words for this level. This is a selected deck, not the entire syllabus vocabulary list.`)+`<div class="toolbar">${btn('Due for review','card-filter','data-filter="due"',cardFilter==='due'?'':'secondary')}${btn('All cards','card-filter','data-filter="all"',cardFilter==='all'?'':'secondary')}${btn('Browse word list','vocab-list','','ghost')}</div>${c?`<div class="flash-wrap"><div class="row between"><span class="small muted">Card ${cardIndex+1} of ${deck.length}</span><span class="tag">HSK ${c.level}</span></div><button class="card flashcard mt" style="width:100%;color:var(--ink)" data-action="flip" aria-label="Flip flashcard"><span lang="zh-CN" class="zh">${esc(c.zh)}</span>${cardFlipped?`<p class="py">${esc(c.py)}</p><p>${esc(c.en)}</p>`:'<p class="small muted mt">Think of the meaning, then tap to reveal</p>'}</button><div class="row between mt">${btn('← Previous','card-prev','','secondary')}${btn('▶ Hear word','say-card','','secondary')}${btn('Next →','card-next','','secondary')}</div>${cardFlipped?`<p class="small muted mt">How well did you remember it?</p><div class="row">${btn('Again · 10 minutes','card-rate','data-rating="again"','secondary')}${btn('Good · next interval','card-rate','data-rating="good"')}${btn('Easy · longer interval','card-rate','data-rating="easy"','lime')}</div>`:''}</div>`:empty('✓','All caught up','There are no cards due right now. Browse all cards for extra practice.',btn('Study all cards','card-filter','data-filter="all"'))}`;}
function originalGrammarEntries(){return D.grammar.filter(x=>x.level===S.level).map(g=>`<details><summary lang="zh-CN">${esc(g.text)}</summary><p class="py">${esc(py(g.text))}</p><p>${esc(g.en)}</p><div class="explanation">${esc(g.explanation)}</div><div class="row">${btn('▶ Listen','say','data-text="'+esc(g.text)+'"','secondary tiny')}${btn('Build this sentence','one-grammar',`data-id="${g.id}"`,'tiny')}</div></details>`).join('');}
function grammarSearchKey(value){return String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
function filteredGrammar(search=grammarSearch,filter=grammarFilter){
 const query=grammarSearchKey(search.trim()),compact=query.replace(/\s+/g,'');
 return (G?.topics||[]).filter(t=>{
  const group=filter==='all'||filter==='course'&&t.kind==='course'||filter==='compare'&&t.kind==='compare'||filter==='review'&&t.kind==='review'||filter==='book-a'&&t.lesson>=1&&t.lesson<=10||filter==='book-b'&&t.lesson>=11&&t.lesson<=20||filter.startsWith('lesson-')&&t.lesson===Number(filter.slice(7));
  const hay=grammarSearchKey([t.title,t.pattern,t.explanation,t.tip,...t.examples.flatMap(x=>[x.text,x.en,x.py])].join(' '));
  return group&&(!query||hay.includes(query)||hay.replace(/\s+/g,'').includes(compact));
 });
}
function grammarCards(topics){
 if(!topics.length)return '<div class="empty"><h3>No matching topics</h3><p class="muted">Try a Chinese pattern, an English meaning, or another lesson filter.</p></div>';
 return topics.map(t=>`<details data-grammar-id="${t.id}"><summary>${esc(t.title)}</summary><p class="small muted">${t.lesson?`Book 4${t.lesson<=10?'上 (A)':'下 (B)'} · Lesson ${t.lesson} · ${t.kind==='compare'?'Word comparison':'Language point'}`:'Foundation review · Earlier grammar used at HSK 4'}</p><p><strong>Pattern:</strong> ${esc(t.pattern)}</p><div class="explanation">${esc(t.explanation)}</div><p class="small"><strong>Remember:</strong> ${esc(t.tip)}</p>${t.examples.map((ex,i)=>`<section class="mt" aria-label="Example ${i+1}"><p class="zh" lang="zh-CN">${esc(ex.text)}</p><p class="py">${esc(ex.py)}</p><p class="translation">${esc(ex.en)}</p><div class="row">${btn('▶ Listen','say',`data-text="${esc(ex.text)}"`,'secondary tiny')}${btn('Build this sentence','one-grammar',`data-id="${ex.id}"`,'tiny')}</div></section>`).join('')}</details>`).join('');
}
function updateGrammarResults(){const topics=filteredGrammar();$('#grammar-count').textContent=`${topics.length} of ${G.topics.length} topics`;$('#grammar-results').innerHTML=grammarCards(topics);}
function grammarGroups(){return [['all','All 150 topics'],['course','100 course language points'],['compare','20 word comparisons'],['review','30 foundation reviews'],['book-a','Book 4上 (A) · Lessons 1–10'],['book-b','Book 4下 (B) · Lessons 11–20'],...Array.from({length:20},(_,i)=>['lesson-'+(i+1),'Lesson '+(i+1)+' · 5 points + 1 comparison'])];}
function examTopicOptions(){return grammarGroups().filter(([value])=>value!=='all').map(([value,label])=>'<label class="grammar-topic-option"><input type="checkbox" name="exam-group" value="'+value+'" checked> <span>'+esc(label)+'</span></label>').join('');}
function selectedExamTopics(){const ids=new Set();document.querySelectorAll('[name="exam-group"]:checked').forEach(c=>filteredGrammar('',c.value).forEach(t=>ids.add(t.id)));return [...ids];}
function grammarExamSetup(){
 const topics=G.topics;
 modal('<h2>Grammar exam</h2><p>Choose lessons or categories, a set, and how many questions to answer. Each set has one question per topic. Answers appear after submission.</p><p class="small muted">Construction-based practice: sets change activity contexts while reusing grammar constructions. These are not 7,500 independently authored questions.</p><div class="row">'+btn('Select all sections','grammar-select-all','','secondary tiny')+btn('Clear selection','grammar-clear','','ghost tiny')+'</div><fieldset class="grammar-topic-picker"><legend>Lessons and categories</legend>'+examTopicOptions()+'</fieldset><p id="exam-selection-count" role="status">'+topics.length+' topics selected</p><div class="toolbar"><div class="field"><label for="grammar-set">Exam set</label><select id="grammar-set">'+Array.from({length:50},(_,i)=>'<option value="'+(i+1)+'">Set '+(i+1)+'</option>').join('')+'</select></div><div class="field"><label for="grammar-question-count">Questions to answer</label><input id="grammar-question-count" type="number" min="1" max="'+topics.length+'" value="'+topics.length+'" required></div></div><p class="small muted">Fill in the blank and sentence ordering. No timer. A shorter exam samples your selected topics; select the full count to cover them all.</p>'+(S.active?'<p class="notice warn">Starting replaces your unfinished session.</p>':'')+'<div class="row mt">'+btn('Start exam','start-grammar-exam')+btn('Cancel','close-modal','','secondary')+'</div>');
}
function updateExamSelection(){const n=selectedExamTopics().length;$('#exam-selection-count').textContent=n+' topics selected';const input=$('#grammar-question-count');input.max=String(n);input.value=String(n);$('[data-action="start-grammar-exam"]').disabled=!n;}
function grammar(){
 if(S.level!==4||!G)return heading('UNDERSTAND THE PATTERN',`HSK ${S.level} grammar guide`,'Open a pattern for its meaning, pinyin, explanation, and a sentence to practise.')+`<div class="card grammar-entry mt">${originalGrammarEntries()}</div>`;
 const groups=grammarGroups();
 const topics=filteredGrammar();
 return '<div class="row">'+btn('Take a grammar exam →','grammar-exam')+'</div>'+heading('UNDERSTAND THE PATTERN','HSK 4 grammar guide','HSK 2.0 · 100 Standard Course language points, 20 word comparisons, and 30 foundation reviews. Each topic has two examples with pinyin, English, audio, and sentence practice.')+`<div class="toolbar"><div class="field" style="flex:1 1 260px;min-width:0"><label for="grammar-search">Find a pattern</label><input id="grammar-search" type="search" value="${esc(grammarSearch)}" placeholder="Try 连, only if, or suizhe" style="width:100%;min-width:0"></div><div class="field" style="flex:1 1 280px;min-width:0"><label for="grammar-filter">Study section</label><select id="grammar-filter" style="width:100%;min-width:0;max-width:100%">${groups.map(([value,label])=>`<option value="${value}" ${value===grammarFilter?'selected':''}>${label}</option>`).join('')}</select></div></div><div class="row between"><span class="small muted" id="grammar-count" role="status" aria-live="polite">${topics.length} of ${G.topics.length} topics</span><div class="row">${btn('Expand results','grammar-expand','','secondary tiny')}${btn('Collapse results','grammar-collapse','','ghost tiny')}</div></div><div id="grammar-results" class="card grammar-entry mt">${grammarCards(topics)}</div><details class="card grammar-entry mt"><summary>Earlier practice sentences · 30 examples</summary><p class="small muted">Your original examples are kept here. Some include extension patterns beyond the textbook checklist.</p>${originalGrammarEntries()}</details><details class="card mt"><summary>Coverage and references</summary><p class="small">${esc(G.scope)}</p><p class="small">The 100 course points and 20 comparisons follow the lesson indexes of the old HSK Standard Course 4上 and 4下. Explanations and examples are newly written. The 30 foundation topics review earlier grammar needed at this level. Pinyin shows dictionary tones with neutral-tone readings; pronunciation can change in connected speech.</p><ul class="help-list">${G.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)}</a></li>`).join('')}</ul></details>`;
}
function review(){let list=Object.values(reviewTab==='bookmarks'?S.bookmarks:S.mistakes).filter(x=>x.q?.level===S.level&&(reviewTab==='bookmarks'||!x.resolved));return heading('TURN “NOT YET” INTO “GOT IT”','Your review notebook','Every incorrect answer is saved here. Correctly retrying a question clears it from active mistakes.')+`<div class="toolbar">${btn('Mistakes','review-tab','data-tab="mistakes"',reviewTab==='mistakes'?'':'secondary')}${btn('Bookmarks','review-tab','data-tab="bookmarks"',reviewTab==='bookmarks'?'':'secondary')}${list.length?btn('Practise this list →',reviewTab==='bookmarks'?'bookmark-drill':'mistake-drill','','lime'):''}</div>${list.length?`<div class="card">${list.map(x=>`<div class="list-item"><div><span class="tag">${esc(x.q.section)} · ${esc(x.q.type)}</span><p lang="zh-CN" style="font-size:19px;margin:9px 0 2px">${esc(x.q.type==='free'?x.q.word:x.q.prompt||x.q.text)}</p><span class="small muted">${x.count?`${x.count} incorrect attempt${x.count>1?'s':''} · `:''}${esc(x.q.explanation?.slice(0,105)||'Review the answer and explanation.')}</span></div>${btn('Retry','retry-one',`data-key="${esc(qkey(x.q))}" data-tab="${reviewTab}"`,'secondary tiny')}</div>`).join('')}</div>`:empty('↺','A fresh page',reviewTab==='bookmarks'?'Use the star on any question to save it here.':'Mistakes will appear here after you check answers or finish an exam.',btn('Start practising','nav','data-view="practice"'))}`;}
function progress(){const st=stats();return heading('SEE HOW FAR YOU HAVE COME','Your progress','Counts and accuracy reflect practice, not official HSK scores.')+`<div class="grid three mt"><div class="card stat"><div class="eyebrow">Finished sessions</div><div class="stat-num">${st.h.length}</div></div><div class="card stat"><div class="eyebrow">Answers scored</div><div class="stat-num">${st.total}</div><span class="small muted">Includes explicitly self-rated writing</span></div><div class="card stat"><div class="eyebrow">Practice accuracy</div><div class="stat-num">${st.total?st.accuracy+'%':'—'}</div></div></div><div class="grid two mt"><div class="card"><h3>The last 28 days</h3><p class="small muted">All levels · Checked answers and rated flashcards</p><div class="heatmap">${Array.from({length:28},(_,i)=>{let d=new Date();d.setDate(d.getDate()-27+i);let k=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,n=S.days[k]||0;return `<div class="day ${n>=S.settings.goal?'strong':n?'done':''}" title="${k}: ${n} activities" aria-label="${k}: ${n} activities"></div>`;}).join('')}</div><p class="small muted">Darker green means you reached your daily goal.</p></div><div class="card"><h3>Accuracy by section</h3>${['listening','reading','writing'].map(s=>{let rows=st.h.flatMap(h=>h.sections||[]).filter(x=>x.name===s),t=rows.reduce((a,x)=>a+x.total,0),c=rows.reduce((a,x)=>a+x.correct,0),p=t?Math.round(c/t*100):0;return `<div class="bar-row"><span>${s}</span><div class="progress"><span style="width:${p}%"></span></div><span>${t?p+'%':'—'}</span></div>`;}).join('')}</div></div><div class="section-head"><h2>Recent sessions</h2>${btn('Export progress','export','','secondary tiny')}</div><div class="card">${st.h.length?st.h.slice().reverse().slice(0,25).map(h=>`<div class="list-item"><div><strong>${esc(h.title)}</strong><div class="small muted">${new Date(h.date).toLocaleString()} · ${esc(h.mode)} ${h.unrated?`· ${h.unrated} unrated`:''}</div></div><span class="tag">${h.correct}/${h.total} scored</span></div>`).join(''):'<p class="muted">Finish a session to see it here.</p>'}</div>`;}
function plan(){let tasks=[['Day 1 · Find your starting point',['Take one full practice paper','Review every incorrect answer','Study 20 due vocabulary cards']],['Day 2 · Listen for meaning',['Complete a listening section','Practise ten dictation sentences','Replay difficult recordings and read the transcript']],['Day 3 · Read with purpose',['Complete a reading section','Review five grammar patterns','Retry your unresolved reading mistakes']],['Day 4 · Put sentences together',['Complete a writing section','Practise word order and character recall','Compare five picture sentences with model answers']],['Day 5 · Bring it together',['Take another timed full paper','Review recurring mistakes','Revise familiar words and leave time to rest']]];return heading('A PLAN YOU CAN ACTUALLY FOLLOW','Five days, one clear focus','Use this as a flexible final-revision plan. Each checkbox is saved on this device.')+`<div class="notice mt">Choose the day that matches your preparation. You can work through this plan at your own pace; it is not a promise of exam readiness.</div><div class="stack mt">${tasks.map(([title,items],i)=>`<div class="card"><h3>${title}</h3><div class="checklist">${items.map((t,j)=>`<label><input type="checkbox" data-plan="${S.level}-${i}-${j}" ${S.plan[`${S.level}-${i}-${j}`]?'checked':''}><span>${t}</span></label>`).join('')}</div></div>`).join('')}</div>`;}
function settings(){return heading('MAKE THIS YOUR STUDY SPACE','Settings & help')+`<div class="grid two mt"><div class="card"><h3>Study preferences</h3><div class="stack"><div class="field"><label for="theme">Appearance</label><select id="theme"><option value="light" ${S.settings.theme==='light'?'selected':''}>Light</option><option value="dark" ${S.settings.theme==='dark'?'selected':''}>Dark</option></select></div><div class="field"><label for="font">Chinese text size</label><input id="font" type="range" min="20" max="36" value="${S.settings.font}"></div><div class="field"><label for="goal">Daily activity goal</label><input id="goal" type="number" min="5" max="200" value="${S.settings.goal}"></div><div class="field"><label for="voice">Mandarin voice</label><select id="voice">${voiceOptions()}</select></div><div class="field"><label for="speed">Practice playback speed</label><select id="speed">${[.6,.75,.9,1,1.1,1.2].map(s=>`<option value="${s}" ${s===S.settings.speed?'selected':''}>${s}×</option>`).join('')}</select></div>${btn('▶ Test Mandarin audio','say','data-text="你好，欢迎一起学习汉语。"','secondary')}</div><p class="small muted mt">Voices come from your device or browser. Some require internet access. If none appear, install a Simplified Chinese speech voice in your operating system or try another browser.</p></div><div class="stack"><div class="card"><h3>Your progress stays with you</h3><p class="muted small">Saved locally in this browser. Clearing site data removes progress. Back up before changing devices.</p><div class="row">${btn('Export backup','export')}${btn('Import backup','import','','secondary')}<input class="hidden" type="file" id="import-file" accept="application/json,.json"></div></div><div class="card"><h3>Offline study</h3><p class="muted small">After the first successful online visit on GitHub Pages, the site caches its files. Speech works offline only when the selected voice supports it. No external fonts, CSS libraries, or paid APIs are required.</p><p class="small muted" id="offline-status">${'serviceWorker' in navigator?'Offline caching is supported by this browser.':'This browser does not support offline caching.'}</p>${btn('Check for site update','update','','secondary tiny')}</div><div class="card"><h3>Start fresh</h3><p class="small muted">This deletes progress from this browser only.</p>${btn('Reset all progress','reset','','danger tiny')}</div></div></div><div class="card mt"><h3>How the practice works</h3><ul class="help-list"><li><strong>100 practice forms:</strong> 50 for each level, assembled deterministically from the same original bank. Different forms reuse question families and change names or selections. They are not 100 independently authored past papers.</li><li><strong>Counts:</strong> HSK 3 uses 40 listening, 30 reading, 10 writing; HSK 4 uses 45 listening, 40 reading, 15 writing.</li><li><strong>Timing:</strong> active section timers are 35/30/15 minutes for HSK 3 and 30/40/25 for HSK 4. Registration and answer-transfer time are excluded. Section timers keep running when you leave or reload.</li><li><strong>Format adaptations:</strong> listening comprehension uses short narrated scenarios, rather than reproducing official multi-speaker dialogues and grouped long recordings. Images are symbolic illustrations. Cloze and matching tasks use shared answer pools.</li><li><strong>Practice mode:</strong> check each answer immediately. <strong>Timed mode:</strong> answers stay hidden until submission; completed sections lock. Audio is replayable, so this is a timed study exercise, not secure examination software.</li><li><strong>Writing:</strong> character and ordering tasks use a normalised model answer. Alternative valid orders can be self-marked after feedback. Picture sentences need self-assessment; there is no AI grammar grader.</li><li><strong>Pinyin:</strong> generated using a phrase dictionary with context corrections. It generally shows dictionary tones; connected speech may change tones. Study glosses accompany answer feedback.</li><li><strong>Scope:</strong> selected grammar and vocabulary are geared toward HSK 2.0 levels 3–4; a few extension words appear in scenarios. This is not a complete audited syllabus course. No professional linguistic review has been performed.</li></ul><p class="small">Format references: <a href="https://www.chinesetest.cn/HSK/3" target="_blank" rel="noopener">Official HSK 3 structure</a> · <a href="https://www.chinesetest.cn/HSK/4" target="_blank" rel="noopener">Official HSK 4 structure</a></p><p class="small muted">Keyboard: 1–6 selects an answer; Enter checks it in practice mode. Left/right arrows move between questions. Shortcuts do not run while you type.</p></div>`;}
function empty(icon,title,desc,action=''){return `<div class="card empty mt"><div class="empty-icon">${icon}</div><h2>${title}</h2><p class="muted">${desc}</p>${action}</div>`;}
function modal(html){stopSpeech();$('.modal-backdrop')?.remove();const d=document.createElement('div');d.className='modal-backdrop';d.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="Study options">${html}</section>`;document.body.append(d);d.querySelector('button,input,select')?.focus();}
function closeModal(){$('.modal-backdrop')?.remove();}
function setup(paper,section){modal(`<p class="eyebrow">HSK ${S.level} · PAPER ${paper}</p><h2>${section==='all'?'Full paper':section[0].toUpperCase()+section.slice(1)}</h2><p class="muted">How would you like to study?</p><div class="field"><label for="run-mode">Study mode</label><select id="run-mode"><option value="practice">Practice · check answers as you go</option><option value="exam">Timed · reveal answers after submission</option></select></div><p class="small muted mt">${section==='all'?'All three sections in order. Each section has its own timer in timed mode.':'Work on this section on its own.'} Timing excludes registration and answer-transfer time.</p>${S.active?'<div class="notice warn">Starting a new session replaces your unfinished session. Its already checked answers remain in your review notebook.</div>':''}<div class="row mt">${btn('Start session →','start-paper',`data-paper="${paper}" data-section="${section}"`)}${btn('Cancel','close-modal','','secondary')}</div>`);}
function start(questions,title,{mode='practice',paper=null,section='drill'}={}){stopSpeech();closeModal();session={id:String(Date.now()),level:S.level,title,questions,mode,paper,section,answers:{},checked:{},self:{},flags:{},tokens:{},index:0,phase:questions[0]?.section||'reading',phaseStarted:Date.now(),deadline:null,started:Date.now(),finished:false};if(mode==='exam')session.deadline=Date.now()+duration(session.phase)*60000;index=0;S.active=session;save();view='exam';render();window.scrollTo(0,0);}
function duration(section){return ({3:{listening:35,reading:30,writing:15},4:{listening:30,reading:40,writing:25}})[session?.level||S.level][section]||15;}
function visible(q){return session.finished||(session.mode==='practice'&&Object.hasOwn(session.checked,q.id));}
function isLocked(q){return session.finished||(session.mode==='exam'&&q.section!==session.phase)||(session.mode==='practice'&&Object.hasOwn(session.checked,q.id));}
function response(q){return session.answers[q.id]||'';}
function renderExam(){if(!session){view='home';render();return;}const q=current();if(!q){view='home';render();return;}let answered=session.questions.filter(x=>response(x)).length,v=visible(q),locked=isLocked(q),key=qkey(q),pos=session.questions.filter(x=>x.section===q.section).findIndex(x=>x.id===q.id)+1;const sections=[...new Set(session.questions.map(x=>x.section))];shell(`<div class="row between" style="margin-bottom:20px"><div><p class="eyebrow">${esc(session.title)}</p><h2>${q.section[0].toUpperCase()+q.section.slice(1)} <span class="muted">/ Part ${q.part||1}</span></h2></div><div class="row"><span class="tag">${session.finished?'ANSWER REVIEW':session.mode==='exam'?'TIMED MODE':session.mode==='grammar-exam'?'GRAMMAR EXAM':'PRACTICE MODE'}</span>${btn(session.finished?'Back to results':'Save & leave',session.finished?'results':'leave','','secondary tiny')}</div></div><div class="exam-layout"><div><article class="card question-card"><div class="question-meta"><span>QUESTION ${index+1} OF ${session.questions.length} ${q.group?' · '+esc(q.group):''}</span><div class="row"><button class="btn ghost tiny" data-action="bookmark" aria-label="Bookmark question" aria-pressed="${!!S.bookmarks[key]}">${S.bookmarks[key]?'★':'☆'}</button><button class="btn ghost tiny" data-action="flag" aria-pressed="${!!session.flags[q.id]}">${session.flags[q.id]?'⚑ Flagged':'⚐ Flag'}</button></div></div>${renderQuestion(q,v,locked)}${v?feedback(q):''}<div class="actions">${btn('← Previous','prev',index===0?'disabled':'','secondary')}${!v&&session.mode==='practice'?btn('Check answer','check',!response(q)?'disabled':''):''}${index<session.questions.length-1?btn('Next →','next','','secondary'):!session.finished?btn('Finish session','finish','','lime'):btn('View results','results')}</div></article>${session.mode==='exam'&&!session.finished?`<p class="small muted mt">Answers are hidden until you finish. When the timer expires, this section locks. Leaving this page does not pause the timer.</p>`:''}</div><aside class="exam-side"><div class="card"><div class="row between"><span class="eyebrow">${session.mode==='exam'&&!session.finished?'Time remaining':'Your session'}</span></div>${session.mode==='exam'&&!session.finished?'<div id="timer" class="timer" aria-label="Time remaining">'+minutes(Math.max(0,Math.ceil((session.deadline-Date.now())/1000)))+'</div>':`<div class="stat-num">${answered}<span class="small muted"> / ${session.questions.length}</span></div>`}<div class="progress"><span style="width:${answered/session.questions.length*100}%"></span></div><p class="small muted">${answered} answered · ${Object.values(session.flags).filter(Boolean).length} flagged</p>${sections.map(s=>`<p class="eyebrow mt">${s}</p><div class="jump-grid">${session.questions.map((x,i)=>x.section===s?`<button class="jump ${i===index?'current':''} ${response(x)?'answered':''} ${session.flags[x.id]?'flagged':''}" data-action="jump" data-index="${i}" aria-label="Question ${i+1}" ${session.mode==='exam'&&!session.finished&&s!==session.phase?'disabled':''}>${i+1}</button>`:'').join('')}</div>`).join('')}<div class="stack mt">${!session.finished?btn(session.mode==='exam'&&session.phase!==sections.at(-1)?'Finish this section':'Submit session','finish','','secondary tiny'):btn('Results summary','results','','secondary tiny')}</div></div><p class="small muted mt">${q.type==='free'?'Picture writing is self-assessed.':q.type==='order'?'Tap a word to add it. Tap it again in the answer area to remove it.':'Choose carefully. The explanation is part of the learning.'}</p></aside></div>`);}
function renderQuestion(q,v,locked){let html='';const listening=q.section==='listening'||q.type==='dictation';if(listening){html+=`<div class="listen-panel"><button class="playbig" data-action="play" aria-label="Play Mandarin recording">▶</button><div><div class="wave" aria-hidden="true">${'<i></i>'.repeat(15)}</div><p class="small muted" style="margin:5px 0 0">Mandarin speech · ${session.level===3&&q.type!=='dictation'?'plays twice':'one reading'}</p></div>${btn('Stop','stop','','ghost tiny')}${session.mode==='practice'?`<label class="small">Speed <select id="inline-speed" aria-label="Playback speed">${[.6,.75,.9,1,1.1,1.2].map(s=>`<option value="${s}" ${s===S.settings.speed?'selected':''}>${s}×</option>`).join('')}</select></label>`:''}</div><p id="audio-status" class="small muted" role="status">Press play to listen. Audio is generated by your browser.</p>`;}
 if(q.type==='gap'){return '<p class="prompt zh" lang="zh-CN">'+esc(q.prompt)+'</p><p class="small muted">Complete the blank. Target pattern: '+esc(q.hint)+'</p><label class="label" for="written-answer">Missing Chinese expression</label><input id="written-answer" lang="zh-CN" autocomplete="off" maxlength="40" value="'+esc(response(q))+'" '+(locked?'disabled':'')+'>'; }
 if(q.type==='order'||q.type==='sequence'){
 html+=`<p class="prompt">${esc(q.prompt)}</p>${q.type==='order'?'<p class="small muted">Arrange every word chunk. Punctuation is attached to some chunks.</p>':'<p class="small muted">Tap the sentences in their logical order.</p>'}`;
 const used=session.tokens[q.id]||[];html+=`<div class="answer-zone" aria-label="Your arranged answer">${used.length?used.map((t,j)=>`<button class="token" lang="zh-CN" data-action="remove-token" data-index="${j}" ${locked?'disabled':''}>${esc(q.tokens[t])}</button>`).join(''):'<span class="small muted">Your answer will appear here…</span>'}</div><div class="token-area">${q.tokens.map((t,i)=>`<button class="token" lang="zh-CN" data-action="add-token" data-index="${i}" ${locked||used.includes(i)?'disabled':''}>${esc(t)}</button>`).join('')}</div>${!locked?btn('Clear order','clear-order','','ghost tiny'):''}`;
 }else if(q.type==='character')html+=`<p class="small muted">Write the missing character. Hint: <strong>${esc(q.hint)}</strong></p><p class="zh" lang="zh-CN">${esc(q.prompt)}</p><label class="label" for="written-answer">Your Chinese character</label><input id="written-answer" lang="zh-CN" class="zh" autocomplete="off" maxlength="4" value="${esc(response(q))}" ${locked?'disabled':''}>`;
 else if(q.type==='free')html+=`<p>${esc(q.prompt)}</p><div class="illustration" role="img" aria-label="Picture-writing illustration">${esc(q.icon)}</div><p>Required word: ${zh(q.word)}</p><label class="label" for="written-answer">Write one complete Chinese sentence</label><textarea id="written-answer" lang="zh-CN" class="zh" maxlength="500" ${locked?'disabled':''}>${esc(response(q))}</textarea><p class="small muted">The model is one possible answer. You will assess your own sentence.</p>`;
 else if(q.type==='dictation')html+=`<label class="label" for="written-answer">Type the sentence you hear</label><textarea id="written-answer" lang="zh-CN" class="zh" ${locked?'disabled':''}>${esc(response(q))}</textarea>`;
 else{
 if(!listening&&q.text)html+=`<div class="passage zh" lang="zh-CN">${esc(q.text)}</div>`;
 html+=`<p class="prompt" ${/[\u4e00-\u9fff]/.test(q.prompt)?'lang="zh-CN"':''}>${esc(q.prompt)}</p>`;
 if(q.promptEn&&!listening)html+=`<p class="small muted">${esc(q.promptEn)}</p>`;
 html+=`<div class="${q.type==='picture-choice'?'picture-options':''}" role="group" aria-label="Answer choices">${q.options.map((o,i)=>`<button class="option ${response(q)===o.zh?'selected':''} ${v&&o.zh===q.answer?'correct':''} ${v&&response(q)===o.zh&&o.zh!==q.answer?'wrong':''}" data-action="select" data-index="${i}" aria-pressed="${response(q)===o.zh}" ${locked?'disabled':''}><span class="letter">${String.fromCharCode(65+i)}</span>${o.icon?`<span class="icon" role="img" aria-label="${esc(o.en)}">${esc(o.icon)}</span>`:zh(o.zh)}</button>`).join('')}</div>`;
 }return html;}
function feedback(q){let val=session.checked[q.id],full=q.fullText||q.text||q.answer,correct=val===true,unrated=val===null;return `<section class="feedback" aria-live="polite"><h3 class="${val===false?'incorrect':''}">${unrated?'Compare your sentence':session.self[q.id]!==undefined?(correct?'✓ Self-assessed: valid':'Self-assessed: needs practice'):correct?'✓ Correct':'Let’s look at the answer'}</h3>${q.type!=='free'?`<p class="small muted">Model answer</p><p lang="zh-CN" style="font-size:23px">${esc(q.answer)}</p><p class="py">${esc(py(q.answer))}</p>`:''}<div class="explanation">${esc(q.explanation)}</div>${full?`<p class="eyebrow">${q.section==='listening'?'Recording transcript':'Complete example'}</p><p lang="zh-CN" class="zh">${esc(full)}</p><p class="py">${esc(py(full))}</p><p class="translation">${esc(q.en)}</p>${btn('▶ Hear full example','say',`data-text="${esc(full)}"`,'secondary tiny')}`:''}${q.promptEn&&q.type!=='free'?`<p class="translation mt">Question: ${esc(q.promptEn)}</p>${/[\u4e00-\u9fff]/.test(q.prompt)?`<p class="py">${esc(py(q.prompt))}</p>`:''}`:''}${q.options?`<details class="mt"><summary>All choices · pinyin & English</summary>${q.options.map(o=>`<p>${zh(o.zh)} <span class="py">${esc(py(o.zh))}</span><br><span class="translation">${esc(o.en)}</span></p>`).join('')}</details>`:''}${['free','order','sequence','dictation'].includes(q.type)?`<div class="notice mt">${q.type==='free'?'Check: does your sentence describe the illustration, use the given word, and form a complete grammatical sentence?':'A different valid answer may be marked incorrect by exact comparison. Only self-mark it if you have checked the Chinese carefully.'}<div class="row mt">${btn('My answer is valid','self-mark','data-value="true"','secondary tiny')}${btn('Needs more practice','self-mark','data-value="false"','secondary tiny')}</div>${session.self[q.id]!==undefined?'<p class="small mt">Your self-assessment has been recorded.</p>':''}</div>`:''}</section>`;}
function record(q,correct){const key=qkey(q);S.days[dateKey()]=(Number(S.days[dateKey()])||0)+1;if(correct===false){S.mistakes[key]={q,count:(Number(S.mistakes[key]?.count)||0)+1,date:Date.now(),resolved:false};}else if(correct===true&&S.mistakes[key])S.mistakes[key].resolved=true;const tk=session.level+':'+q.section;const t=S.tags[tk]||{total:0,correct:0};if(correct!==null){t.total++;if(correct)t.correct++;}S.tags[tk]=t;}
function check(){const q=current();if(visible(q)||(session.mode==='exam'||session.mode==='grammar-exam'))return;if(!response(q)){toast('Choose or write an answer first.');return;}if(['order','sequence'].includes(q.type)&&(session.tokens[q.id]||[]).length!==q.tokens.length){toast('Use every chunk before checking.');return;}const result=E.evaluate(q,response(q));session.checked[q.id]=result;record(q,result);save();renderExam();}
function finishPrompt(){let phaseQs=session.questions.filter(q=>session.mode==='exam'?q.section===session.phase:true),left=phaseQs.filter(q=>!response(q)).length;modal(`<h2>${session.mode==='exam'?'Submit this section?':'Finish your session?'}</h2><p>${left?`You still have ${left} unanswered question${left===1?'':'s'}. Unanswered objective questions count as incorrect.`:'All questions in this section have an answer.'}</p><p class="small muted">${session.mode==='exam'?'This locks the current section. Answers are revealed when the session ends.':'You can review every answer after finishing.'}</p><div class="row mt">${btn('Submit','confirm-finish')}${btn('Keep working','close-modal','','secondary')}</div>`);}
function advance(auto=false){closeModal();stopSpeech();const sections=[...new Set(session.questions.map(q=>q.section))],p=sections.indexOf(session.phase);if(session.mode==='exam'&&p<sections.length-1){session.phase=sections[p+1];session.deadline=(auto?session.deadline:Date.now())+duration(session.phase)*60000;index=session.questions.findIndex(q=>q.section===session.phase);session.index=index;save();if(auto)toast('Time is up. The next section has started.');view='exam';renderExam();return;}complete();}
function complete(){for(const q of session.questions){if(!Object.hasOwn(session.checked,q.id)){const result=E.evaluate(q,response(q));session.checked[q.id]=result;record(q,result);}}session.finished=true;session.ended=Date.now();S.active=null;saveHistory();save();view='results';render();window.scrollTo(0,0);}
function summary(){let rated=session.questions.filter(q=>typeof session.checked[q.id]==='boolean'),correct=rated.filter(q=>session.checked[q.id]).length;return {total:rated.length,correct,unrated:session.questions.length-rated.length,sections:[...new Set(session.questions.map(q=>q.section))].map(name=>{let qs=session.questions.filter(q=>q.section===name&&typeof session.checked[q.id]==='boolean');return {name,total:qs.length,correct:qs.filter(q=>session.checked[q.id]).length};})};}
function saveHistory(){const s=summary(),entry={id:session.id,title:session.title,level:session.level,paper:session.paper,section:session.section,mode:session.mode,date:session.ended||Date.now(),...s};let i=S.history.findIndex(h=>h.id===session.id);if(i>=0)S.history[i]=entry;else S.history.push(entry);S.history=S.history.slice(-200);}
function renderResults(){if(!session?.finished){view='home';render();return;}let s=summary(),pct=s.total?Math.round(s.correct/s.total*100):0;shell(heading('ONE SESSION STRONGER','Here’s how you did',esc(session.title))+`<div class="grid two mt"><div class="card" style="text-align:center"><div class="score-ring" style="--pct:${pct}"><div class="score-inner"><strong>${pct}%</strong><span class="small muted">practice accuracy</span></div></div><h2>${s.correct} / ${s.total} scored answers</h2><p class="small muted">${s.unrated?`${s.unrated} open-writing answer(s) still need your self-assessment.`:'Includes your self-assessed writing, if any.'}</p><p class="small muted">This is not an official HSK score or pass prediction.</p></div><div class="card"><h3>Section breakdown</h3>${s.sections.map(x=>`<div class="list-item"><span>${x.name[0].toUpperCase()+x.name.slice(1)}</span><strong>${x.correct}/${x.total}</strong></div>`).join('')}<div class="row mt">${btn('Review every answer','review-session')}${btn('Retry incorrect answers','retry-session','','secondary')}</div></div></div><div class="notice mt">${s.unrated?'Open the answer review and compare your written sentences with the models. Valid alternatives are welcome.':'Read the explanation for every mistake before retrying. Understanding why is more useful than memorising a letter.'}</div><div class="row mt">${btn('Return to mock exams','nav','data-view="papers"','secondary')}${btn('Export progress','export','','ghost')}</div>`);}
function drill(kind){const r=E.rng(kind==='daily'?Number(dateKey().replaceAll('-',''))+S.level:Date.now()|0),paper=E.assemble(S.level,1+Math.floor(r()*50));let qs,title;
 if(kind==='mistake-drill'||kind==='bookmark-drill'){qs=Object.values(kind==='mistake-drill'?S.mistakes:S.bookmarks).filter(x=>x.q?.level===S.level&&(kind==='bookmark-drill'||!x.resolved)).map(x=>x.q);title=kind==='mistake-drill'?'Mistake workout':'Bookmarked questions';if(!qs.length){toast('No questions in this list yet.');return;}qs=E.shuffle(qs,r).slice(0,30);}
 else if(kind==='dictation'){qs=E.shuffle(D.grammar.filter(x=>x.level===S.level),r).slice(0,10).map(x=>({...x,sourceId:x.id,section:'listening',part:1,type:'dictation',audio:x.text,answer:x.text,prompt:'Listen and write the sentence.'}));title='Sentence dictation';}
 else if(kind==='vocab-quiz'){qs=E.shuffle(vocabDeck(),r).slice(0,10).map(v=>{let opts=E.shuffle([v,...E.shuffle(vocabDeck().filter(x=>x.id!==v.id),r).slice(0,3)],r);return {id:v.id,sourceId:v.id,level:S.level,section:'reading',part:1,type:'choice',prompt:`What does ${v.zh} mean?`,text:'',fullText:v.zh,en:v.en,options:opts.map(x=>({zh:x.en,en:x.en})),answer:v.en,explanation:`${v.zh} (${v.py}) means ${v.en}.`,tag:'Vocabulary'};});title='Vocabulary meanings';}
 else{let filter=kind==='listen-drill'?q=>q.section==='listening':kind==='read-drill'?q=>q.section==='reading'&&q.part===3:kind==='grammar-drill'?q=>q.section==='reading'&&q.fullText&&q.type==='choice':kind==='order-drill'?q=>q.type==='order':kind==='char-drill'?q=>q.type==='character':kind==='picture-drill'?q=>q.type==='free':()=>true;if(kind==='char-drill'&&S.level===4){qs=E.assemble(3,1).filter(q=>q.type==='character').map(q=>({...q,level:4}));}else if(kind==='picture-drill'&&S.level===3){qs=E.assemble(4,1).filter(q=>q.type==='free').map(q=>({...q,level:3}));}else qs=E.shuffle(paper.filter(filter),r).slice(0,10);title=({'listen-drill':'Listening sprint','read-drill':'Reading sprint','grammar-drill':'Grammar gaps','order-drill':'Sentence builder','char-drill':'Character recall · foundational review','picture-drill':'Picture writing · extension practice',daily:'Daily challenge',quick:'Mixed warm-up'})[kind];}
 launchDrill(qs,title);}
function launchDrill(qs,title){const run=()=>start(qs.map((q,i)=>({...q,id:'drill-'+i})),title);if(S.active){modal(`<h2>Start ${esc(title)}?</h2><p>This replaces your unfinished session. Checked answers remain saved.</p><div class="row">${btn('Start new session','pending-start')}${btn('Resume existing','resume','','secondary')}${btn('Cancel','close-modal','','ghost')}</div>`);pendingStart=run;}else run();}
let pendingStart=null;
function stopSpeech(){speechToken++;if('speechSynthesis'in window)speechSynthesis.cancel();}
function refreshVoices(){voices='speechSynthesis'in window?speechSynthesis.getVoices().filter(v=>/^(zh|cmn)/i.test(v.lang)):[];if($('#voice'))$('#voice').innerHTML=voiceOptions();}
function voiceOptions(){return `<option value="">${voices.length?'Automatic Mandarin voice':'No Mandarin voice detected'}</option>`+voices.map(v=>`<option value="${esc(v.voiceURI)}" ${S.settings.voice===v.voiceURI?'selected':''}>${esc(v.name)} · ${v.localService?'device voice':'may need internet'}</option>`).join('');}
function say(text,repeats=1){stopSpeech();refreshVoices();if(!('speechSynthesis'in window)){toast('Speech synthesis is not supported in this browser.');return;}let voice=voices.find(v=>v.voiceURI===S.settings.voice)||voices.find(v=>/zh[-_]CN/i.test(v.lang))||voices[0];if(!voice){toast('No Mandarin voice found. Open Settings & help for setup instructions.');if($('#audio-status'))$('#audio-status').textContent='No Mandarin voice is installed. Open Settings & help to choose a voice.';return;}const token=speechToken;let count=0;function play(){if(token!==speechToken)return;const u=new SpeechSynthesisUtterance(text);u.lang=voice.lang;u.voice=voice;u.rate=session&&!session.finished&&session.mode==='exam'&&view==='exam'?1:S.settings.speed;u.onstart=()=>{if($('#audio-status'))$('#audio-status').textContent=`Playing ${count+1} of ${repeats}…`;};u.onerror=e=>{if(e.error!=='canceled'&&e.error!=='interrupted')toast('Audio could not play. Try another Mandarin voice or check your connection.');};u.onend=()=>{count++;if(count<repeats&&token===speechToken)setTimeout(play,900);else if($('#audio-status'))$('#audio-status').textContent='Playback finished. You can replay when ready.';};speechSynthesis.speak(u);}play();}
function exportData(){save();const blob=new Blob([JSON.stringify(S,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`hsk-studio-progress-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Progress backup downloaded.');}
function changeIndex(i){const q=session.questions[i];if(!q)return;if(session.mode==='exam'&&!session.finished&&q.section!==session.phase){if(i>index)finishPrompt();else toast('That section is locked until answer review.');return;}stopSpeech();index=i;session.index=i;if(!session.finished)save();renderExam();}
function selfMark(value){const q=current();session.checked[q.id]=value;session.self[q.id]=value;const k=qkey(q);if(value){if(S.mistakes[k])S.mistakes[k].resolved=true;}else S.mistakes[k]={q,count:S.mistakes[k]?.count||1,date:Date.now(),resolved:false};if(session.finished)saveHistory();save();renderExam();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;
 if(a==='nav'){stopSpeech();if(session&&!session.finished){session.index=index;save();}view=b.dataset.view;closeModal();render();window.scrollTo(0,0);return;}
 if(a==='level'||a==='level-papers'){S.level=Number(b.dataset.level);cardIndex=0;cardFlipped=false;save();view=a==='level-papers'?'papers':view==='exam'||view==='results'?'home':view;render();return;}
 if(a==='menu'){$('#sidebar').classList.toggle('open');return;}
 if(a==='grammar-exam'){grammarExamSetup();return;}
 if(a==='grammar-select-all'||a==='grammar-clear'){document.querySelectorAll('[name="exam-group"]').forEach(c=>c.checked=a==='grammar-select-all');updateExamSelection();return;}
 if(a==='start-grammar-exam'){try{const ids=selectedExamTopics(),set=Number($('#grammar-set').value),count=Number($('#grammar-question-count').value);const qs=window.HSK_GRAMMAR_EXAMS.assemble(set,ids,count);start(qs,'HSK 4 grammar · Set '+set+' · '+count+' questions',{mode:'grammar-exam',section:'grammar'});}catch(err){toast(err.message);}return;}
 if(a==='setup'){setup(Number(b.dataset.paper),b.dataset.section);return;}
 if(a==='close-modal'){closeModal();return;}
 if(a==='start-paper'){const paper=Number(b.dataset.paper),section=b.dataset.section,mode=$('#run-mode').value;start(E.assemble(S.level,paper).filter(q=>section==='all'||q.section===section),`HSK ${S.level} · Paper ${String(paper).padStart(2,'0')} · ${section==='all'?'Full paper':section}`,{mode,paper,section});return;}
 if(a==='resume'){closeModal();if(S.active){session=S.active;S.level=session.level;index=session.index||0;view='exam';tick();render();}else toast('No unfinished session.');return;}
 if(a==='pending-start'){pendingStart?.();pendingStart=null;return;}
 if(['quick','daily','listen-drill','read-drill','grammar-drill','order-drill','char-drill','picture-drill','dictation','mistake-drill','bookmark-drill','vocab-quiz'].includes(a)){drill(a);return;}
 if(a==='grammar-expand'||a==='grammar-collapse'){$('#grammar-results')?.querySelectorAll('details').forEach(d=>{d.open=a==='grammar-expand';});return;}
 if(a==='one-grammar'){const x=guideExamples.get(b.dataset.id)||D.grammar.find(g=>g.id===b.dataset.id);if(!x){toast('This example is unavailable. Reload the page and try again.');return;}launchDrill([{...x,sourceId:x.id,section:'writing',part:1,type:'order',tokens:E.shuffle(x.chunks,E.rng(Date.now()|0)),prompt:'Arrange the words into a sentence.'}],'Grammar sentence builder');return;}
 if(a==='say'){say(b.dataset.text);return;}if(a==='stop'){stopSpeech();return;}
 if(a==='export'){exportData();return;}if(a==='import'){$('#import-file').click();return;}
 if(a==='update'){if('serviceWorker'in navigator)navigator.serviceWorker.getRegistration().then(r=>r?r.update().then(()=>toast('Update checked. Reload the site to use any downloaded update.')):toast('No offline worker is active yet. Open the site over HTTPS.')).catch(()=>toast('Update check failed. Check your connection.'));return;}
 if(a==='reset'){modal(`<h2>Delete all saved progress?</h2><p>This removes completed sessions, mistakes, bookmarks, flashcard schedules, and your current session from this browser.</p><div class="row">${btn('Export first','export','','secondary')}${btn('Delete progress','confirm-reset','','danger')}${btn('Cancel','close-modal','','ghost')}</div>`);return;}
 if(a==='confirm-reset'){stopSpeech();S=defaults();session=null;save();closeModal();view='home';render();return;}
 if(a==='review-tab'){reviewTab=b.dataset.tab;render();return;}
 if(a==='retry-one'){let item=(b.dataset.tab==='bookmarks'?S.bookmarks:S.mistakes)[b.dataset.key];if(item)launchDrill([item.q],'Focused review');return;}
 if(a==='card-filter'){cardFilter=b.dataset.filter;cardIndex=0;cardFlipped=false;render();return;}
 if(a==='flip'){cardFlipped=!cardFlipped;render();return;}
 if(a==='card-prev'||a==='card-next'){const len=filteredCards().length;cardIndex=(cardIndex+(a==='card-next'?1:-1)+len)%len;cardFlipped=false;render();return;}
 if(a==='say-card'){const c=filteredCards()[cardIndex];if(c)say(c.zh);return;}
 if(a==='card-rate'){const c=filteredCards()[cardIndex];if(!c)return;const old=S.cards[c.id]?.interval||0,r=b.dataset.rating,interval=r==='again'?0:r==='good'?Math.max(1,Math.round(old*2)):Math.max(3,Math.round(old*3));S.cards[c.id]={interval,due:Date.now()+(r==='again'?600000:interval*86400000)};S.days[dateKey()]=(Number(S.days[dateKey()])||0)+1;if(cardFilter==='all')cardIndex=(cardIndex+1)%filteredCards().length;cardFlipped=false;save();render();return;}
 if(a==='vocab-list'){modal(`<h2>Focused revision words</h2><p class="small muted">${vocabDeck().length} selected words · HSK ${S.level}</p>${vocabDeck().map(c=>`<div class="vocab-row"><span lang="zh-CN">${esc(c.zh)}</span><span class="py">${esc(c.py)}</span><span>${esc(c.en)}</span></div>`).join('')}<div class="mt">${btn('Close','close-modal')}</div>`);return;}
 if(!session)return;const q=current();
 if(a==='select'){if(isLocked(q))return;session.answers[q.id]=q.options[Number(b.dataset.index)].zh;save();renderExam();return;}
 if(a==='add-token'||a==='remove-token'||a==='clear-order'){if(isLocked(q))return;let arr=session.tokens[q.id]||[];if(a==='add-token'&&!arr.includes(Number(b.dataset.index)))arr.push(Number(b.dataset.index));if(a==='remove-token')arr.splice(Number(b.dataset.index),1);if(a==='clear-order')arr=[];session.tokens[q.id]=arr;session.answers[q.id]=arr.map(i=>q.tokens[i]).join('');save();renderExam();return;}
 if(a==='check'){check();return;}
 if(a==='self-mark'){selfMark(b.dataset.value==='true');return;}
 if(a==='next'){changeIndex(index+1);return;}if(a==='prev'){changeIndex(index-1);return;}if(a==='jump'){changeIndex(Number(b.dataset.index));return;}
 if(a==='play'){say(q.audio||q.text,session.level===3&&q.type!=='dictation'?2:1);return;}
 if(a==='bookmark'){const k=qkey(q);if(S.bookmarks[k])delete S.bookmarks[k];else S.bookmarks[k]={q,date:Date.now()};save();renderExam();return;}
 if(a==='flag'){session.flags[q.id]=!session.flags[q.id];save();renderExam();return;}
 if(a==='finish'){finishPrompt();return;}if(a==='confirm-finish'){advance();return;}
 if(a==='leave'){stopSpeech();session.index=index;save();view='home';render();return;}
 if(a==='results'){view='results';render();return;}if(a==='review-session'){index=0;view='exam';render();return;}
 if(a==='retry-session'){const qs=session.questions.filter(q=>session.checked[q.id]===false);if(!qs.length){toast('No incorrect answers to retry. Review any unrated writing first.');return;}launchDrill(qs,'Retry incorrect answers');return;}
});
document.addEventListener('input',e=>{if(e.target.id==='grammar-search'){grammarSearch=e.target.value;updateGrammarResults();return;}if(e.target.id==='written-answer'&&session&&!isLocked(current())){session.answers[current().id]=e.target.value;save();const checkBtn=$('[data-action="check"]');if(checkBtn)checkBtn.disabled=!e.target.value.trim();}if(e.target.id==='paper-search'){paperSearch=e.target.value.trim();$('#paper-grid').innerHTML=paperGrid();}if(e.target.id==='font'){S.settings.font=Number(e.target.value);document.documentElement.style.setProperty('--zh',S.settings.font+'px');save();}});
document.addEventListener('change',async e=>{const t=e.target;if(t.name==='exam-group'){updateExamSelection();return;}if(t.id==='grammar-filter'){grammarFilter=t.value;updateGrammarResults();return;}if(t.dataset.plan){S.plan[t.dataset.plan]=t.checked;save();return;}if(t.id==='paper-filter'){paperFilter=t.value;$('#paper-grid').innerHTML=paperGrid();return;}if(['theme','voice','speed','inline-speed','goal'].includes(t.id)){const key=t.id==='inline-speed'?'speed':t.id;S.settings[key]=['speed','goal'].includes(key)?Number(t.value):t.value;if(key==='goal')S.settings.goal=Math.min(200,Math.max(5,S.settings.goal||30));save();if(t.id!=='inline-speed')render();return;}if(t.id==='import-file'&&t.files[0]){try{if(t.files[0].size>8000000)throw Error('Backup is too large.');const incoming=validate(JSON.parse(await t.files[0].text()));modal(`<h2>Restore this backup?</h2><p>This replaces the progress currently saved in this browser.</p><div class="row">${btn('Restore backup','pending-start')}${btn('Cancel','close-modal','','secondary')}</div>`);pendingStart=()=>{stopSpeech();S=incoming;session=null;save();closeModal();view='home';render();toast('Progress restored.');};}catch(err){toast('Could not import: '+err.message);}t.value='';}});
document.addEventListener('keydown',e=>{if($('.modal-backdrop')){if(e.key==='Escape')closeModal();if(e.key==='Tab'){const a=[...$('.modal').querySelectorAll('button,input,select,a')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===a[0]){e.preventDefault();a.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===a.at(-1)){e.preventDefault();a[0]?.focus();}}return;}if(view!=='exam'||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='ArrowRight'){e.preventDefault();changeIndex(index+1);}if(e.key==='ArrowLeft'){e.preventDefault();changeIndex(index-1);}if(e.key==='Enter'&&e.target.tagName!=='BUTTON'){e.preventDefault();check();}if(/^[1-6]$/.test(e.key)){const b=$(`[data-action="select"][data-index="${Number(e.key)-1}"]`);b?.click();}});
function tick(){if(!session||session.finished||session.mode!=='exam')return;while(!session.finished&&Date.now()>=session.deadline){advance(true);}if(session.finished)return;const t=$('#timer');if(t){const secs=Math.ceil((session.deadline-Date.now())/1000);t.textContent=minutes(secs);t.classList.toggle('low',secs<300);}}
setInterval(tick,1000);window.addEventListener('beforeunload',()=>{stopSpeech();save();});window.addEventListener('online',()=>{if($('#connection'))$('#connection').textContent='Ready to study';});window.addEventListener('offline',()=>{if($('#connection'))$('#connection').textContent='Offline mode';});
if('speechSynthesis'in window){refreshVoices();speechSynthesis.addEventListener('voiceschanged',refreshVoices);}
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{console.info('Offline caching unavailable. The site still works online.');});
render();
})();
